WITH lines AS (SELECT id, host, log_ts, status_code, key, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, value) SELECT *, LAG(status_code, 1) OVER (PARTITION BY host, key ORDER BY log_ts, id, key) prev_status_code, COUNT(status_code) OVER (PARTITION BY key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) status_code_count_1h, FIRST_VALUE(key, TRUE) OVER (PARTITION BY key, host ORDER BY log_ts, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_key, COUNT(status_code) OVER (PARTITION BY key) key_count_status_code FROM lines
